  request: Request,
) {
  await enforceRateLimit(environment, request, "service-account-update", 60, 60);
  if (body.name === undefined && body.description === undefined && body.ownerId === undefined) {
    throw new M1Error(400);
  }
  if ((body.ownerId === undefined) !== (body.ownerType === undefined)) throw new M1Error(400);

  const db = createDb(environment.DB);
  const current = await db
    .select()
    .from(serviceAccounts)
    .innerJoin(principals, eq(principals.id, serviceAccounts.principalId))
    .where(and(eq(serviceAccounts.principalId, principalId), eq(principals.type, "service")))
    .get();
  if (!current) throw new M1Error(404);
  const name = body.name === undefined ? current.service_accounts.name : normalizeServiceAccountName(body.name);
  const description =
    body.description === undefined
      ? current.service_accounts.description
      : normalizeDescription(body.description);
  const ownership =
    body.ownerId === undefined
      ? {
          ownerUserPrincipalId: current.service_accounts.ownerUserPrincipalId,
          ownerTeamId: current.service_accounts.ownerTeamId,
          owner: await readOwner(db, current.service_accounts.ownerUserPrincipalId, current.service_accounts.ownerTeamId),
        }
      : await resolveActiveOwner(db, {
          ownerId: body.ownerId,
          ownerType: body.ownerType ?? "user",
        });
  const now = Date.now();
  const changed = db
    .update(serviceAccounts)
    .set({
      name,
      description,
      ownerUserPrincipalId: ownership.ownerUserPrincipalId,
      ownerTeamId: ownership.ownerTeamId,
      updatedAt: now,
    })
    .where(eq(serviceAccounts.principalId, principalId))
    .returning({ id: serviceAccounts.principalId });
  const updated = db
    .select({ value: serviceAccounts.principalId })
    .from(serviceAccounts)
    .where(and(eq(serviceAccounts.principalId, principalId), eq(serviceAccounts.updatedAt, now)));
  const result = await db.batch([
    changed,
    auditStatementWhen(
      db,
      `service-account:updated:${principalId}:${now}`,
      "service_account.updated",
      actor.principalId,
      principalId,
      null,
      { name, description, owner: ownership.owner },
      now,
      updated,
    ),
    outboxStatementWhen(
      db,
      `service-account:updated:outbox:${principalId}:${now}`,
      "service_account.updated",
      "principal",
      principalId,
      { name, description, owner: ownership.owner },
      now,
      updated,
    ),
  ]);
  if (!result[0]?.length) throw new M1Error(409);
  return {
    id: principalId,
    principalId,
    name,
    description,
    status: current.principals.status,
    owner: ownership.owner,
  };
}

export async function transferServiceAccountOwnership(
  environment: AuthEnvironment,
  actor: Actor,
  principalId: string,
  ownership: OwnershipInput,
  request: Request,
) {
  return updateServiceAccount(
    environment,
    actor,
    principalId,
    { ownerId: ownership.ownerId, ownerType: ownership.ownerType },
    request,
  );
}

export async function setServiceAccountDisabled(
  environment: AuthEnvironment,
  actor: Actor,
  principalId: string,
  disabled: boolean,
  request: Request,
) {
  await enforceRateLimit(
    environment,
    request,
    disabled ? "service-account-disable" : "service-account-enable",
    60,
    60,
  );
  const db = createDb(environment.DB);
  const current = await db
    .select({
      principalId: serviceAccounts.principalId,
      status: principals.status,
      ownerUserPrincipalId: serviceAccounts.ownerUserPrincipalId,
      ownerTeamId: serviceAccounts.ownerTeamId,
    })
    .from(serviceAccounts)
    .innerJoin(principals, eq(principals.id, serviceAccounts.principalId))
    .where(eq(serviceAccounts.principalId, principalId))
    .get();
  if (!current) throw new M1Error(404);
  if (current.status === (disabled ? "disabled" : "active")) {
    return { id: principalId, principalId, status: current.status };
  }
  if (!disabled) {
    await resolveActiveOwner(db, {
      ownerId: current.ownerUserPrincipalId ?? current.ownerTeamId ?? "",
      ownerType: current.ownerUserPrincipalId ? "user" : "team",
    });
  }

  const now = Date.now();
  const status = disabled ? "disabled" : "active";
  const changed = db
    .update(principals)
    .set({ status, disabledAt: disabled ? now : null, updatedAt: now })
    .where(
      and(
        eq(principals.id, principalId),
        eq(principals.type, "service"),
        eq(principals.status, disabled ? "active" : "disabled"),
      ),
    )
    .returning({ id: principals.id });
  const updated = db
    .select({ value: principals.id })
    .from(principals)
    .where(and(eq(principals.id, principalId), eq(principals.status, status), eq(principals.updatedAt, now)));
  const result = await db.batch([
    changed,
    auditStatementWhen(
      db,
      `service-account:${disabled ? "disabled" : "enabled"}:${principalId}:${now}`,
      `service_account.${disabled ? "disabled" : "enabled"}`,
      actor.principalId,
      principalId,
      null,
      {},
      now,
      updated,
    ),
    outboxStatementWhen(
      db,
      `service-account:${disabled ? "disabled" : "enabled"}:outbox:${principalId}:${now}`,
      `service_account.${disabled ? "disabled" : "enabled"}`,
      "principal",
      principalId,
      { status },
      now,
      updated,
    ),
  ]);
  if (!result[0]?.length) throw new M1Error(409);
  return { id: principalId, principalId, status: status as "active" | "disabled" };
}

async function readOwner(
  database: ReturnType<typeof createDb>,
  ownerUserPrincipalId: string | null,
  ownerTeamId: string | null,
) {
  if (ownerUserPrincipalId) {
    const owner = await database
      .select({ name: user.name, email: user.email })
      .from(user)
      .innerJoin(
        (await import("../../../db/domain-schema")).humanPrincipals,
        eq((await import("../../../db/domain-schema")).humanPrincipals.userId, user.id),
      )
      .where(eq((await import("../../../db/domain-schema")).humanPrincipals.principalId, ownerUserPrincipalId))
      .get();
    return { id: ownerUserPrincipalId, label: owner?.name ?? owner?.email ?? ownerUserPrincipalId, type: "user" as const };
  }
  if (ownerTeamId) {
    const owner = await database.select({ name: teams.name }).from(teams).where(eq(teams.id, ownerTeamId)).get();
    return { id: ownerTeamId, label: owner?.name ?? ownerTeamId, type: "team" as const };
  }
  throw new M1Error(500);
}

import { and, eq, exists, isNull, sql } from "drizzle-orm";

import { createDb } from "../../../db";
import {
  humanPrincipals,
  principals,
  systemRoleGrants,
  systemRoles,
} from "../../../db/domain-schema";
import { type AuthEnvironment } from "../../auth";
import { type Actor } from "../authorization/service";
import { M1Error } from "../errors";
import { activeRootCount, resolveHumanPrincipal } from "../users/service";
import {
  auditStatementWhen,
  enforceRateLimit,
  outboxStatementWhen,
} from "../../shared/infrastructure";

export async function listSystemRoles(environment: AuthEnvironment) {
  const db = createDb(environment.DB);
  const roles = await db.select().from(systemRoles).orderBy(systemRoles.key).all();
  const grants = await db
    .select({ roleId: systemRoleGrants.roleId })
    .from(systemRoleGrants)
    .innerJoin(principals, eq(principals.id, systemRoleGrants.principalId))
    .where(and(isNull(systemRoleGrants.revokedAt), eq(principals.status, "active")))
    .all();
  const counts = new Map<string, number>();
  for (const grant of grants) counts.set(grant.roleId, (counts.get(grant.roleId) ?? 0) + 1);

  return roles.map((role) => ({
    key: role.key,
    name: role.name,
    description: role.description,
    activeGrantCount: counts.get(role.id) ?? 0,
  }));
}

export async function grantSystemRole(
  environment: AuthEnvironment,
  actor: Actor,
  identifier: string,
  roleKey: string,
  request: Request,
) {
  await enforceRateLimit(environment, request, "system-role-grant", 120, 60);
  const db = createDb(environment.DB);
  const target = await resolveHumanPrincipal(db, identifier);
  if (!target || target.principal_status !== "active" || target.human_status !== "active") {
    throw new M1Error(409);
  }
  const role = await db
    .select({ id: systemRoles.id, key: systemRoles.key })
    .from(systemRoles)
    .where(eq(systemRoles.key, roleKey))
    .get();
  if (!role) throw new M1Error(400);

  const current = await db
    .select({ id: systemRoleGrants.id, revokedAt: systemRoleGrants.revokedAt })
    .from(systemRoleGrants)
    .where(
      and(eq(systemRoleGrants.principalId, target.principal_id), eq(systemRoleGrants.roleId, role.id)),
    )
    .get();
  if (current && current.revokedAt === null) {
    return {
      principalId: target.principal_id,
      roleKey: role.key,
      status: "granted" as const,
      userId: target.user_id,
    };
  }

  const now = Date.now();
  const grantId = current?.id ?? `system-role:${target.principal_id}:${role.id}`;
  const mutation = current
    ? db
        .update(systemRoleGrants)
        .set({ grantedByPrincipalId: actor.principalId, revokedAt: null, createdAt: now })
        .where(and(eq(systemRoleGrants.id, grantId), isNull(systemRoleGrants.revokedAt)))
        .returning({ id: systemRoleGrants.id })
    : db
        .insert(systemRoleGrants)
        .values({
          id: grantId,
          principalId: target.principal_id,
          roleId: role.id,
          grantedByPrincipalId: actor.principalId,
          revokedAt: null,
          createdAt: now,
        })
        .onConflictDoUpdate({
          target: [systemRoleGrants.principalId, systemRoleGrants.roleId],
          set: { grantedByPrincipalId: actor.principalId, revokedAt: null, createdAt: now },
        })
        .returning({ id: systemRoleGrants.id });
  const activeGrant = db
    .select({ value: systemRoleGrants.id })
    .from(systemRoleGrants)
    .where(
      and(
        eq(systemRoleGrants.principalId, target.principal_id),
        eq(systemRoleGrants.roleId, role.id),
        isNull(systemRoleGrants.revokedAt),
      ),
    );
  const result = await db.batch([
    mutation,
    auditStatementWhen(
      db,
      `system-role:granted:${target.principal_id}:${role.key}:${now}`,
      "system_role.granted",
      actor.principalId,
      target.principal_id,
      target.user_id,
      { roleKey: role.key },
      now,
      activeGrant,
    ),
    outboxStatementWhen(
      db,
      `system-role:granted:outbox:${target.principal_id}:${role.key}:${now}`,
      "system_role.granted",
      "principal",
      target.principal_id,
      { roleKey: role.key },
      now,
      activeGrant,
    ),
  ]);
  if (!result[0]?.length) throw new M1Error(409);
  return {
    principalId: target.principal_id,
    roleKey: role.key,
    status: "granted" as const,
    userId: target.user_id,
  };
}

export async function revokeSystemRole(
  environment: AuthEnvironment,
  actor: Actor,
  identifier: string,
  roleKey: string,
  request: Request,
) {
  await enforceRateLimit(environment, request, "system-role-revoke", 120, 60);
  const db = createDb(environment.DB);
  const target = await resolveHumanPrincipal(db, identifier);
  if (!target) throw new M1Error(404);
  const role = await db
    .select({ id: systemRoles.id, key: systemRoles.key })
    .from(systemRoles)
    .where(eq(systemRoles.key, roleKey))
    .get();
  if (!role) throw new M1Error(404);
  const current = await db
    .select({ id: systemRoleGrants.id, revokedAt: systemRoleGrants.revokedAt })
    .from(systemRoleGrants)
    .where(
      and(eq(systemRoleGrants.principalId, target.principal_id), eq(systemRoleGrants.roleId, role.id)),
    )
    .get();
  if (!current || current.revokedAt !== null) {
    return {
      principalId: target.principal_id,
      roleKey: role.key,
      status: "revoked" as const,
      userId: target.user_id,
    };
  }
  if (role.key === "root" && (await activeRootCount(db)) <= 1) throw new M1Error(409);

  const now = Date.now();
  const activeRoots = db
    .select({ count: sql<number>`count(*)` })
    .from(principals)
    .innerJoin(humanPrincipals, eq(humanPrincipals.principalId, principals.id))
    .innerJoin(systemRoleGrants, eq(systemRoleGrants.principalId, principals.id))
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(principals.type, "human"),
        eq(principals.status, "active"),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
        isNull(systemRoleGrants.revokedAt),
        eq(systemRoles.key, "root"),
      ),
    );
  const canRevoke = role.key === "root" ? sql`(${activeRoots}) > 1` : sql`1 = 1`;
  const mutation = db
    .update(systemRoleGrants)
    .set({ revokedAt: now })
    .where(
      and(
        eq(systemRoleGrants.id, current.id),
        isNull(systemRoleGrants.revokedAt),
        canRevoke,
      ),
    )
    .returning({ id: systemRoleGrants.id });
  const revokedGrant = db
    .select({ value: systemRoleGrants.id })
    .from(systemRoleGrants)
    .where(and(eq(systemRoleGrants.id, current.id), eq(systemRoleGrants.revokedAt, now)));
  const result = await db.batch([
    mutation,
    auditStatementWhen(
      db,
      `system-role:revoked:${target.principal_id}:${role.key}:${now}`,
      "system_role.revoked",
      actor.principalId,
      target.principal_id,
      target.user_id,
      { roleKey: role.key },
      now,
      revokedGrant,
    ),
    outboxStatementWhen(
      db,
      `system-role:revoked:outbox:${target.principal_id}:${role.key}:${now}`,
      "system_role.revoked",
      "principal",
      target.principal_id,
      { roleKey: role.key },
      now,
      revokedGrant,
    ),
  ]);
  if (!result[0]?.length) throw new M1Error(409);
  return {
    principalId: target.principal_id,
    roleKey: role.key,
    status: "revoked" as const,
    userId: target.user_id,
  };
}

