import { assertMutationOrigin } from "./http";
import { M2Models } from "./models";
import {
  createServiceAccount,
  listServiceAccounts,
  setServiceAccountDisabled,
  transferServiceAccountOwnership,
  updateServiceAccount,
} from "./service-accounts/service";
import {
  addTeamMember,
  createTeam,
