  removeTeamMember,
  setTeamDisabled,
  updateTeam,
} from "./teams/service";
import { listSystemRoles, grantSystemRole, revokeSystemRole } from "./system-roles/service";
import { listUsers, repairHumanPrincipal } from "./users/service";

export function createM2Routes(environment: AuthEnvironment, auth: AuthInstance) {
  return new Elysia({ name: "shui-m2-routes", normalize: false })
    .use(createAuthorizationPlugin(environment, auth))
    .model(M2Models)
    .prefix("model", "M2.")
    .error({ M1Error })
    .onBeforeHandle(({ request, set }) => {
      if (["POST", "PUT", "PATCH", "DELETE"].includes(request.method)) {
        assertMutationOrigin(environment, request);
      }
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
    })
    .onError(({ code, error, set }) => {
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
      const statusCode =
        error instanceof M1Error ? error.statusCode : code === "VALIDATION" ? 400 : 500;
      set.status = statusCode;
      return {
        error: statusCode >= 500 ? "Request failed." : "The request could not be completed.",
      };
    })
    .get(
      "/users",
      async () => ({ users: await listUsers((await import("../../db")).createDb(environment.DB)) }),
      { requireRole: ["root", "user-admin"], response: "M2.Users" },
    )
    .post(
      "/users/:id/repair",
      async ({ actor, params, request }) => repairHumanPrincipal(environment, actor, params.id, request),
      {
        params: "M2.IdentifierParams",
        requireRole: ["root", "user-admin"],
        response: "M2.UserRepair",
      },
    )
    .get(
      "/system-roles",
      async () => ({ roles: await listSystemRoles(environment) }),
      { requireRole: ["root", "user-admin"], response: "M2.SystemRoles" },
    )
    .post(
      "/users/:id/system-roles",
      async ({ actor, body, params, request }) =>
        grantSystemRole(environment, actor, params.id, body.roleKey, request),
      {
        body: "M2.SystemRoleGrantBody",
        params: "M2.IdentifierParams",
        requireRole: ["root"],
        response: "M2.SystemRoleGrant",
      },
    )
    .delete(
      "/users/:id/system-roles/:roleKey",
      async ({ actor, params, request }) =>
        revokeSystemRole(environment, actor, params.id, params.roleKey, request),
      {
        params: "M2.UserRoleParams",
        requireRole: ["root"],
        response: "M2.SystemRoleGrant",
      },
    )
    .get(
      "/teams",
      async () => ({ teams: await listTeams(environment) }),
      { requireRole: ["root", "user-admin"], response: "M2.Teams" },
    )
    .post(
      "/teams",
      async ({ actor, body, request }) => createTeam(environment, actor, body, request),
      { body: "M2.TeamCreateBody", requireRole: ["root", "user-admin"], response: "M2.TeamCreated" },
    )
    .patch(
      "/teams/:id",
      async ({ actor, body, params, request }) =>
        updateTeam(environment, actor, params.id, body, request),
      {
        body: "M2.TeamUpdateBody",
        params: "M2.IdentifierParams",
        requireRole: ["root", "user-admin"],
        response: "M2.TeamCreated",
      },
