+    { method: "POST" },
+  );
+}
+
+export async function grantUserRole(id: string, roleKey: string) {
+  return m2Fetch(`/users/${encodeURIComponent(id)}/system-roles`, {
+    body: JSON.stringify({ roleKey }),
+    method: "POST",
+  });
+}
+
+export async function revokeUserRole(id: string, roleKey: string) {
+  return m2Fetch(`/users/${encodeURIComponent(id)}/system-roles/${encodeURIComponent(roleKey)}`, {
+    method: "DELETE",
+  });
+}
+
+export async function getTeams() {
+  return m2Fetch<{ teams: M2Team[] }>("/teams");
+}
+
+export async function createTeam(body: M2TeamCreateBody) {
+  return m2Fetch<M2Team>("/teams", { body: JSON.stringify(body), method: "POST" });
+}
+
+export async function updateTeam(id: string, body: M2TeamUpdateBody) {
+  return m2Fetch<M2Team>(`/teams/${encodeURIComponent(id)}`, {
+    body: JSON.stringify(body),
+    method: "PATCH",
+  });
+}
+
+export async function setTeamStatus(id: string, status: "active" | "disabled") {
+  return m2Fetch(`/teams/${encodeURIComponent(id)}/${status === "disabled" ? "disable" : "enable"}`, {
+    method: "POST",
+  });
+}
+
+export async function deleteTeam(id: string) {
+  return m2Fetch(`/teams/${encodeURIComponent(id)}`, { method: "DELETE" });
+}
+
+export async function addTeamMember(teamId: string, body: M2TeamMemberBody) {
+  return m2Fetch(`/teams/${encodeURIComponent(teamId)}/members`, {
+    body: JSON.stringify(body),
+    method: "POST",
+  });
+}
+
+export async function removeTeamMember(teamId: string, userId: string) {
+  return m2Fetch(
+    `/teams/${encodeURIComponent(teamId)}/members/${encodeURIComponent(userId)}`,
+    { method: "DELETE" },
+  );
+}
+
+export async function getServiceAccounts() {
+  return m2Fetch<{ serviceAccounts: M2ServiceAccount[] }>("/service-accounts");
