import type {
  M2OwnershipBody,
  M2ServiceAccountCreateBody,
  M2ServiceAccountUpdateBody,
  M2TeamCreateBody,
  M2TeamMemberBody,
  M2TeamUpdateBody,
} from "../server/modules/models";

export type M2User = {
  createdAt: number;
  disabled: boolean;
  email: string;
  emailVerified: boolean;
  humanStatus: "active" | "disabled" | null;
  id: string;
  name: string;
  principalId: string | null;
  roles: string[];
  status: "active" | "disabled" | "unmanaged";
  teams: Array<{ id: string; name: string; status: "active" | "disabled" }>;
};

export type M2Team = {
  createdAt: number;
  description: string | null;
  id: string;
  memberCount: number;
  members: Array<{ email: string; id: string; name: string; principalId: string }>;
  name: string;
  status: "active" | "disabled";
  updatedAt: number;
};

export type M2ServiceAccount = {
  createdAt: number;
  description: string | null;
  id: string;
  name: string;
  owner: { id: string; label: string; type: "user" | "team" };
  principalId: string;
  status: "active" | "disabled";
  updatedAt: number;
};

export type M2SystemRole = {
  activeGrantCount: number;
  description: string;
  key: string;
  name: string;
};

export class M2ClientError extends Error {
  constructor(
    message: string,
    readonly status: number,
  ) {
    super(message);
    this.name = "M2ClientError";
  }
}

export async function m2Fetch<T>(path: string, init: RequestInit = {}) {
  const headers = new Headers(init.headers);
  if (init.body && !headers.has("content-type")) headers.set("content-type", "application/json");
  const response = await fetch(`/api${path}`, { ...init, headers });
  const body = (await response.json().catch(() => null)) as { error?: string } | T | null;
  if (!response.ok) {
    const message =
      body && typeof body === "object" && "error" in body && typeof body.error === "string"
        ? body.error
        : "The request could not be completed.";
    throw new M2ClientError(message, response.status);
  }
  return body as T;
}

export async function getUsers() {
  return m2Fetch<{ users: M2User[] }>("/users");
}

export async function repairUser(id: string) {
  return m2Fetch<{ principalId: string; status: "active" | "repaired"; userId: string }>(
    `/users/${encodeURIComponent(id)}/repair`,
    { method: "POST" },
  );
}

export async function setUserStatus(id: string, status: "active" | "disabled") {
  return m2Fetch<{ status: "active" | "disabled"; userId: string }>(
    `/users/${encodeURIComponent(id)}/${status === "disabled" ? "disable" : "enable"}`,
    { method: "POST" },
  );
}

export async function grantUserRole(id: string, roleKey: string) {
  return m2Fetch(`/users/${encodeURIComponent(id)}/system-roles`, {
    body: JSON.stringify({ roleKey }),
    method: "POST",
  });
}

export async function revokeUserRole(id: string, roleKey: string) {
  return m2Fetch(`/users/${encodeURIComponent(id)}/system-roles/${encodeURIComponent(roleKey)}`, {
    method: "DELETE",
  });
}

export async function getTeams() {
  return m2Fetch<{ teams: M2Team[] }>("/teams");
}

export async function createTeam(body: M2TeamCreateBody) {
