}

export async function addTeamMember(teamId: string, body: M2TeamMemberBody) {
  return m2Fetch(`/teams/${encodeURIComponent(teamId)}/members`, {
    body: JSON.stringify(body),
    method: "POST",
  });
}

export async function removeTeamMember(teamId: string, userId: string) {
  return m2Fetch(
    `/teams/${encodeURIComponent(teamId)}/members/${encodeURIComponent(userId)}`,
    { method: "DELETE" },
  );
}

export async function getServiceAccounts() {
  return m2Fetch<{ serviceAccounts: M2ServiceAccount[] }>("/service-accounts");
}

export async function createServiceAccount(body: M2ServiceAccountCreateBody) {
  return m2Fetch<M2ServiceAccount>("/service-accounts", {
    body: JSON.stringify(body),
    method: "POST",
  });
}

export async function updateServiceAccount(id: string, body: M2ServiceAccountUpdateBody) {
  return m2Fetch<M2ServiceAccount>(`/service-accounts/${encodeURIComponent(id)}`, {
    body: JSON.stringify(body),
    method: "PATCH",
  });
}

export async function transferServiceAccount(id: string, body: M2OwnershipBody) {
  return m2Fetch<M2ServiceAccount>(
    `/service-accounts/${encodeURIComponent(id)}/transfer-ownership`,
    { body: JSON.stringify(body), method: "POST" },
  );
}

export async function setServiceAccountStatus(id: string, status: "active" | "disabled") {
  return m2Fetch(`/service-accounts/${encodeURIComponent(id)}/${status === "disabled" ? "disable" : "enable"}`, {
    method: "POST",
  });
}

export async function getSystemRoles() {
  return m2Fetch<{ roles: M2SystemRole[] }>("/system-roles");
}

export function formatM2Error(error: unknown) {
  if (error instanceof M2ClientError) {
    if (error.status === 401) return "Sign in with an administrator account to continue.";
    if (error.status === 403) return "Your system role does not allow this action.";
    if (error.status === 409) return "The change conflicts with the current identity state.";
    if (error.status === 429) return "Too many attempts. Wait a moment and try again.";
    return error.message;
  }
  return error instanceof Error && error.message ? error.message : "The request could not be completed.";
}

