              <Button className="text-sm" onClick={() => void signOut()} type="button" variant="ghost">
                Sign out
              </Button>
            </div>
          ) : null}
        </div>
        <nav aria-label="Administration" className="mx-auto flex max-w-7xl gap-1 overflow-x-auto px-4 pb-3 sm:px-7">
          {navigation.map((item) => (
