          <h1 className="mt-4 font-display text-4xl font-semibold leading-none text-kumo-strong sm:text-6xl" id="admin-page-title">
            {title}
          </h1>
          <p className="mt-5 max-w-2xl text-base leading-7 text-kumo-subtle">{description}</p>
        </div>
        <div className="mt-10">{children}</div>
