import { Button, LayerCard } from "@cloudflare/kumo";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";

import {
  formatM2Error,
  getSystemRoles,
  getUsers,
  grantUserRole,
  revokeUserRole,
  type M2SystemRole,
  type M2User,
} from "../lib/m2-client";
import { AdminError, AdminLayout, AdminStatus } from "./admin-layout";

export function SystemRolesAdminPage() {
  const queryClient = useQueryClient();
  const rolesQuery = useQuery({ queryFn: getSystemRoles, queryKey: ["m2", "system-roles"], retry: false });
  const usersQuery = useQuery({ queryFn: getUsers, queryKey: ["m2", "users"], retry: false });
  const [userId, setUserId] = useState("");
  const [roleKey, setRoleKey] = useState("");
  const [busyId, setBusyId] = useState<string>();
  const [error, setError] = useState<string>();
  const [status, setStatus] = useState<string>();

  async function refresh(message?: string) {
    await queryClient.invalidateQueries({ queryKey: ["m2", "system-roles"] });
    await queryClient.invalidateQueries({ queryKey: ["m2", "users"] });
    if (message) setStatus(message);
  }

  async function grant(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!userId || !roleKey) return;
    setBusyId(userId);
    setError(undefined);
    setStatus(undefined);
    try {
      await grantUserRole(userId, roleKey);
      await refresh("System role granted.");
    } catch (grantError) {
      setError(formatM2Error(grantError));
    } finally {
      setBusyId(undefined);
    }
  }

  async function revoke(user: M2User, role: string) {
    if (!window.confirm("Revoke " + role + " from " + user.name + "?")) return;
    setBusyId(user.id);
    setError(undefined);
    setStatus(undefined);
    try {
      await revokeUserRole(user.id, role);
      await refresh("System role revoked.");
    } catch (revokeError) {
      setError(formatM2Error(revokeError));
    } finally {
      setBusyId(undefined);
    }
  }

  const roles = rolesQuery.data?.roles ?? [];
  const users = (usersQuery.data?.users ?? []).filter((user) => user.principalId && user.status !== "unmanaged");
  const selectedRole = roles.find((role) => role.key === roleKey);

  return (
    <AdminLayout
      activePath="/system-roles"
      description="System Roles operate Shui itself. The root role is recovery-critical; the API refuses to remove or disable the last active root User."
      eyebrow="Authorization"
      title="Make responsibility explicit."
    >
      <div className="space-y-8">
        <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
          <h2 className="text-xl font-semibold text-kumo-strong">Grant a system role</h2>
          <form className="mt-5 grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end" onSubmit={grant}>
            <label className="text-sm text-kumo-subtle" htmlFor="role-user">
              User
              <select
                className="mt-2 block min-h-10 w-full rounded-md border border-kumo-line bg-kumo-recessed px-3 text-sm text-kumo-strong focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--tangerine)"
                id="role-user"
                onChange={(event) => setUserId(event.target.value)}
                required
                value={userId}
              >
                <option value="">Choose a User</option>
                {users.map((user) => (
                  <option key={user.id} value={user.id}>
                    {user.name} · {user.email}
                  </option>
                ))}
              </select>
            </label>
            <label className="text-sm text-kumo-subtle" htmlFor="role-key">
              System Role
              <select
                className="mt-2 block min-h-10 w-full rounded-md border border-kumo-line bg-kumo-recessed px-3 text-sm text-kumo-strong focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--tangerine)"
                id="role-key"
                onChange={(event) => setRoleKey(event.target.value)}
                required
                value={roleKey}
              >
                <option value="">Choose a role</option>
                {roles.map((role) => (
                  <option key={role.key} value={role.key}>
                    {role.name}
                  </option>
                ))}
              </select>
            </label>
            <Button aria-busy={busyId === userId} disabled={!userId || !roleKey || busyId !== undefined} type="submit" variant="primary">
              Grant role
            </Button>
          </form>
          {selectedRole ? <p className="mt-4 text-sm leading-6 text-kumo-subtle">{selectedRole.description}</p> : null}
        </LayerCard>
        {rolesQuery.isLoading || usersQuery.isLoading ? <AdminStatus>Loading role assignments...</AdminStatus> : null}
        {rolesQuery.isError ? <AdminError>{formatM2Error(rolesQuery.error)}</AdminError> : null}
        {usersQuery.isError ? <AdminError>{formatM2Error(usersQuery.error)}</AdminError> : null}
        {error ? <AdminError>{error}</AdminError> : null}
        {status ? <AdminStatus>{status}</AdminStatus> : null}
        <div className="grid gap-4 lg:grid-cols-3">
          {roles.map((role) => <RoleCard key={role.key} role={role} users={users} busyId={busyId} onRevoke={revoke} />)}
        </div>
      </div>
    </AdminLayout>
  );
}

function RoleCard({
  busyId,
  onRevoke,
  role,
  users,
}: Readonly<{
  busyId: string | undefined;
  onRevoke: (user: M2User, role: string) => void;
  role: M2SystemRole;
  users: M2User[];
}>) {
  const holders = users.filter((user) => user.roles.includes(role.key));
  return (
    <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
      <div className="flex items-start justify-between gap-3">
        <div>
          <h2 className="text-lg font-semibold text-kumo-strong">{role.name}</h2>
          <p className="mt-1 font-mono text-xs text-(--tangerine)">{role.key}</p>
        </div>
        <span className="text-sm text-kumo-subtle">{role.activeGrantCount} active</span>
      </div>
      <p className="mt-4 text-sm leading-6 text-kumo-subtle">{role.description}</p>
      <div className="mt-5 border-t border-kumo-hairline pt-4">
        <h3 className="text-sm font-medium text-kumo-strong">Current holders</h3>
        {holders.length > 0 ? (
          <ul className="mt-3 space-y-2">
            {holders.map((user) => (
              <li className="flex items-center justify-between gap-3 text-sm" key={user.id}>
                <span className="min-w-0 truncate text-kumo-subtle">{user.name}</span>
                <Button
                  aria-label={"Revoke " + role.name + " from " + user.name}
                  disabled={busyId === user.id}
                  onClick={() => onRevoke(user, role.key)}
                  type="button"
                  variant="ghost"
                >
                  Revoke
                </Button>
              </li>
            ))}
          </ul>
        ) : (
          <p className="mt-3 text-sm text-kumo-subtle">No active holders.</p>
        )}
      </div>
    </LayerCard>
  );
}

