  }
}
import { HeadContent, Scripts } from "@tanstack/react-router";
import type { ReactNode } from "react";

export function RootDocument({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <html data-mode="dark" lang="en">
      <head>
        <HeadContent />
      </head>
      <body>
        {children}
        <Scripts />
      </body>
    </html>
  );
}
import { queryOptions } from "@tanstack/react-query";

import { getTreaty } from "../routes/api.$";

export const healthQueryOptions = queryOptions({
  queryFn: async () => {
    const response = await getTreaty().health.get();

    if (response.error || !response.data) {
      throw new Error("Health check failed");
    }

    return response.data;
  },
  queryKey: ["api", "health"] as const,
  retry: false,
  staleTime: 30_000,
});

export function getSetupRedirect(pathname: string, status: number, available: boolean) {
  const normalizedPath = pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname;

  if (normalizedPath === "/setup") {
    return status === 404 ? "/sign-in" : undefined;
  }

  return available ? "/setup" : undefined;
}
