import { Button, LinkButton } from "@cloudflare/kumo";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import type { ReactNode } from "react";

import { authClient } from "../lib/auth-client";
import { authQueryKeys, sessionQueryOptions } from "../lib/auth-queries";

const navigation = [
  { href: "/users", label: "Users" },
  { href: "/teams", label: "Teams" },
  { href: "/service-accounts", label: "Service accounts" },
  { href: "/system-roles", label: "System roles" },
] as const;

export function AdminLayout({
  activePath,
  children,
  description,
  eyebrow,
  title,
}: Readonly<{
  activePath: (typeof navigation)[number]["href"];
  children: ReactNode;
  description: string;
  eyebrow: string;
  title: string;
}>) {
  const queryClient = useQueryClient();
  const sessionQuery = useQuery(sessionQueryOptions);

  async function signOut() {
    await authClient.signOut();
    await queryClient.invalidateQueries({ queryKey: authQueryKeys.session });
    if (typeof window !== "undefined") window.location.assign("/sign-in");
  }

  return (
    <div className="min-h-screen bg-kumo-canvas">
      <a
        className="sr-only focus:not-sr-only focus:fixed focus:left-4 focus:top-4 focus:z-50 focus:rounded-md focus:bg-kumo-strong focus:px-4 focus:py-3 focus:text-sm focus:text-kumo-canvas"
        href="#admin-content"
      >
        Skip to content
      </a>
      <header className="border-b border-kumo-line bg-kumo-elevated/90">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center gap-4 px-5 py-5 sm:px-8">
          <LinkButton className="m1-wordmark mr-auto" href="/" variant="ghost">
            SHUI<span>/</span>
          </LinkButton>
          <p className="hidden text-xs font-medium uppercase tracking-[0.2em] text-kumo-subtle lg:block">
            Identity control plane
          </p>
          {sessionQuery.data?.user ? (
            <div className="flex items-center gap-3">
              <span className="hidden text-sm text-kumo-subtle sm:inline">
                {sessionQuery.data.user.name || sessionQuery.data.user.email}
              </span>
              <Button
                className="text-sm"
                onClick={() => void signOut()}
                type="button"
                variant="ghost"
              >
                Sign out
              </Button>
            </div>
          ) : null}
        </div>
        <nav
          aria-label="Administration"
          className="mx-auto flex max-w-7xl gap-1 overflow-x-auto px-4 pb-3 sm:px-7"
        >
          {navigation.map((item) => (
            <LinkButton
              aria-current={item.href === activePath ? "page" : undefined}
              className={item.href === activePath ? "bg-kumo-recessed text-kumo-strong" : "text-sm"}
              href={item.href}
              key={item.href}
              variant="ghost"
            >
              {item.label}
            </LinkButton>
          ))}
        </nav>
      </header>
      <section
        aria-labelledby="admin-page-title"
        className="mx-auto max-w-7xl px-5 pb-16 pt-10 sm:px-8 sm:pt-14"
        id="admin-content"
      >
        <div className="max-w-3xl">
          <p className="text-sm font-medium uppercase tracking-[0.18em] text-(--tangerine)">
            {eyebrow}
          </p>
          <h1
            className="mt-4 font-display text-4xl font-semibold leading-none text-kumo-strong sm:text-6xl"
            id="admin-page-title"
          >
            {title}
          </h1>
          <p className="mt-5 max-w-2xl text-base leading-7 text-kumo-subtle">{description}</p>
        </div>
        <div className="mt-10">{children}</div>
      </section>
    </div>
  );
}

export function AdminError({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <p
      className="rounded-lg border border-(--m1-error)/30 bg-(--m1-error)/5 px-4 py-3 text-sm text-(--m1-error)"
      role="alert"
    >
      {children}
    </p>
  );
}

export function AdminStatus({ children }: Readonly<{ children: ReactNode }>) {
  return (
    <p aria-live="polite" className="text-sm text-kumo-brand" role="status">
      {children}
    </p>
  );
}

export function StatusPill({ status }: Readonly<{ status: string }>) {
  return (
    <span className="inline-flex rounded-full border border-kumo-line bg-kumo-recessed px-2.5 py-1 text-xs font-medium text-kumo-subtle">
      {status}
    </span>
  );
}

