import { Button, Input, LayerCard } from "@cloudflare/kumo";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";

import {
  createServiceAccount,
  formatM2Error,
  getServiceAccounts,
  getTeams,
  getUsers,
  setServiceAccountStatus,
  transferServiceAccount,
  updateServiceAccount,
  type M2ServiceAccount,
} from "../lib/m2-client";
import { AdminError, AdminLayout, AdminStatus, StatusPill } from "./admin-layout";

export function ServiceAccountsAdminPage() {
  const queryClient = useQueryClient();
  const accountsQuery = useQuery({
    queryFn: getServiceAccounts,
    queryKey: ["m2", "service-accounts"],
    retry: false,
  });
  const usersQuery = useQuery({ queryFn: getUsers, queryKey: ["m2", "users"], retry: false });
  const teamsQuery = useQuery({ queryFn: getTeams, queryKey: ["m2", "teams"], retry: false });
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [ownerType, setOwnerType] = useState<"user" | "team">("user");
  const [ownerId, setOwnerId] = useState("");
  const [busyId, setBusyId] = useState<string>();
  const [error, setError] = useState<string>();
  const [status, setStatus] = useState<string>();

  async function refresh(message?: string) {
    await queryClient.invalidateQueries({ queryKey: ["m2", "service-accounts"] });
    if (message) setStatus(message);
  }

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(undefined);
    setStatus(undefined);
    setBusyId("create");
    try {
      await createServiceAccount({
        description: description || undefined,
        name,
        ownerId,
        ownerType,
      });
      setName("");
      setDescription("");
      setOwnerId("");
      await refresh("Service account created.");
    } catch (submitError) {
      setError(formatM2Error(submitError));
    } finally {
      setBusyId(undefined);
    }
  }

  async function runAccountAction(id: string, action: () => Promise<unknown>, message: string) {
    setBusyId(id);
    setError(undefined);
    setStatus(undefined);
    try {
      await action();
      await refresh(message);
    } catch (actionError) {
      setError(formatM2Error(actionError));
    } finally {
      setBusyId(undefined);
    }
  }

  const users = (usersQuery.data?.users ?? []).filter(
    (user) => user.principalId && user.status === "active",
  );
  const teams = (teamsQuery.data?.teams ?? []).filter((team) => team.status === "active");
  const accounts = accountsQuery.data?.serviceAccounts ?? [];

  return (
    <AdminLayout
      activePath="/service-accounts"
      description="Service Accounts represent non-human principals. M2 establishes their lifecycle and ownership; OAuth credentials arrive in M4 and are deliberately not mixed into this screen yet."
      eyebrow="Principals / Non-human"
      title="Give automation a responsible owner."
    >
      <div className="space-y-8">
        <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
          <h2 className="text-xl font-semibold text-kumo-strong">New service account</h2>
          <form className="mt-5 grid gap-4 lg:grid-cols-2" onSubmit={submit}>
            <Input
              id="service-name"
              label="Name"
              onChange={(event) => setName(event.target.value)}
              required
              value={name}
            />
            <Input
              id="service-description"
              label="Description (optional)"
              onChange={(event) => setDescription(event.target.value)}
              value={description}
            />
            <label className="text-sm text-kumo-subtle" htmlFor="service-owner-type">
              Owner type
              <select
                className="mt-2 block min-h-10 w-full rounded-md border border-kumo-line bg-kumo-recessed px-3 text-sm text-kumo-strong focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--tangerine)"
                id="service-owner-type"
                onChange={(event) => {
                  const nextType = event.target.value as "user" | "team";
                  setOwnerType(nextType);
                  setOwnerId("");
                }}
                value={ownerType}
              >
                <option value="user">User</option>
                <option value="team">Team</option>
              </select>
            </label>
            <label className="text-sm text-kumo-subtle" htmlFor="service-owner">
              Owner
              <select
                className="mt-2 block min-h-10 w-full rounded-md border border-kumo-line bg-kumo-recessed px-3 text-sm text-kumo-strong focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-(--tangerine)"
                id="service-owner"
                onChange={(event) => setOwnerId(event.target.value)}
                required
                value={ownerId}
              >
                <option value="">Choose an owner</option>
                {ownerType === "user"
                  ? users.map((user) => (
                      <option key={user.principalId} value={user.principalId ?? ""}>
                        {user.name}
                      </option>
                    ))
                  : teams.map((team) => (
                      <option key={team.id} value={team.id}>
                        {team.name}
                      </option>
                    ))}
              </select>
            </label>
            <div className="lg:col-span-2">
              <Button
                aria-busy={busyId === "create"}
                disabled={busyId !== undefined || !ownerId}
                type="submit"
                variant="primary"
              >
                Create service account
              </Button>
            </div>
          </form>
        </LayerCard>
        {accountsQuery.isLoading ? <AdminStatus>Loading service accounts...</AdminStatus> : null}
        {accountsQuery.isError ? (
          <AdminError>{formatM2Error(accountsQuery.error)}</AdminError>
        ) : null}
        {error ? <AdminError>{error}</AdminError> : null}
        {status ? <AdminStatus>{status}</AdminStatus> : null}
        <div className="grid gap-4 lg:grid-cols-2">
          {accounts.map((account) => (
            <ServiceAccountCard
              account={account}
              busy={busyId === account.id}
              key={account.id}
              onStatus={() => {
                const nextStatus = account.status === "active" ? "disabled" : "active";
                void runAccountAction(
                  account.id,
                  () => setServiceAccountStatus(account.id, nextStatus),
                  nextStatus === "active"
                    ? "Service account enabled."
                    : "Service account disabled.",
                );
              }}
              onTransfer={(body) =>
                runAccountAction(
                  account.id,
                  () => transferServiceAccount(account.id, body),
                  "Ownership transferred.",
                )
              }
              onUpdate={(body) =>
                runAccountAction(
                  account.id,
                  () => updateServiceAccount(account.id, body),
                  "Service account updated.",
                )
              }
              teams={teams}
              users={users}
            />
          ))}
        </div>
      </div>
    </AdminLayout>
  );
}

