import { Button, LayerCard } from "@cloudflare/kumo";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";

import { formatM2Error, getUsers, repairUser, setUserStatus, type M2User } from "../lib/m2-client";
import { AdminError, AdminLayout, AdminStatus, StatusPill } from "./admin-layout";

export function UsersAdminPage() {
  const queryClient = useQueryClient();
  const usersQuery = useQuery({ queryFn: getUsers, queryKey: ["m2", "users"], retry: false });
  const [busyId, setBusyId] = useState<string>();
  const [error, setError] = useState<string>();
  const [status, setStatus] = useState<string>();

  async function runAction(id: string, action: () => Promise<unknown>, message: string) {
    setBusyId(id);
    setError(undefined);
    setStatus(undefined);
    try {
      await action();
      await queryClient.invalidateQueries({ queryKey: ["m2", "users"] });
      setStatus(message);
    } catch (actionError) {
      setError(formatM2Error(actionError));
    } finally {
      setBusyId(undefined);
    }
  }

  const users = usersQuery.data?.users ?? [];

  return (
    <AdminLayout
      activePath="/users"
      description="Human identities are the people who can sign in to Shui. Repairing a mapping restores the domain identity without creating a second Better Auth user."
      eyebrow="Principals"
      title="Know who is in the room."
    >
      <div className="space-y-6">
        {usersQuery.isLoading ? <AdminStatus>Loading principals...</AdminStatus> : null}
        {usersQuery.isError ? <AdminError>{formatM2Error(usersQuery.error)}</AdminError> : null}
        {error ? <AdminError>{error}</AdminError> : null}
        {status ? <AdminStatus>{status}</AdminStatus> : null}
        {!usersQuery.isLoading && !usersQuery.isError && users.length === 0 ? (
          <LayerCard className="bg-kumo-elevated p-6 ring ring-kumo-line">
            <h2 className="text-lg font-semibold text-kumo-strong">No users yet</h2>
            <p className="mt-2 text-sm leading-6 text-kumo-subtle">
              Create an invitation to add the first member after setup.
            </p>
          </LayerCard>
        ) : null}
        <div className="grid gap-4 md:grid-cols-2">
          {users.map((user) => (
            <UserCard
              busy={busyId === user.id}
              key={user.id}
              onRepair={() =>
                void runAction(user.id, () => repairUser(user.id), "Principal repaired.")
              }
              onStatus={() => {
                const nextStatus = user.status === "active" ? "disabled" : "active";
                if (nextStatus === "disabled" && !window.confirm("Disable " + user.name + "?"))
                  return;
                void runAction(
                  user.id,
                  () => setUserStatus(user.id, nextStatus),
                  nextStatus === "disabled" ? "User disabled." : "User enabled.",
                );
              }}
              user={user}
            />
          ))}
        </div>
      </div>
    </AdminLayout>
  );
}

function UserCard({
  busy,
  onRepair,
  onStatus,
  user,
}: Readonly<{
  busy: boolean;
  onRepair: () => void;
  onStatus: () => void;
  user: M2User;
}>) {
  const isManaged = user.principalId !== null;
  return (
    <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <h2 className="truncate text-lg font-semibold text-kumo-strong">{user.name}</h2>
          <p className="mt-1 break-all text-sm text-kumo-subtle">{user.email}</p>
        </div>
        <StatusPill status={user.status} />
      </div>
      <dl className="mt-5 grid grid-cols-2 gap-4 border-t border-kumo-hairline pt-4 text-sm">
        <div>
          <dt className="text-kumo-subtle">System roles</dt>
          <dd className="mt-1 text-kumo-strong">{user.roles.join(", ") || "None"}</dd>
        </div>
        <div>
          <dt className="text-kumo-subtle">Teams</dt>
          <dd className="mt-1 text-kumo-strong">{user.teams.length || "None"}</dd>
        </div>
      </dl>
      <p className="mt-4 text-xs text-kumo-subtle">
        Joined {new Date(user.createdAt).toLocaleDateString()} ·{" "}
        {user.emailVerified ? "Email verified" : "Email not verified"}
      </p>
      <div className="mt-5 flex flex-wrap gap-3">
        {isManaged ? (
          <Button
            aria-busy={busy}
            className="text-sm"
            disabled={busy}
            onClick={onStatus}
            type="button"
            variant={user.status === "active" ? "ghost" : "primary"}
          >
            {user.status === "active" ? "Disable user" : "Enable user"}
          </Button>
        ) : (
          <Button
            aria-busy={busy}
            className="text-sm"
            disabled={busy}
            onClick={onRepair}
            type="button"
            variant="primary"
          >
            Repair principal
          </Button>
        )}
      </div>
    </LayerCard>
  );
}

