import { formatM2Error, getUsers, repairUser, setUserStatus, type M2User } from "../lib/m2-client";
import {
  AdminConfirmDialog,
  AdminError,
  AdminLayout,
  AdminStatus,
  StatusPill,
} from "./admin-layout";

const EMPTY_USERS: M2User[] = [];
const userTableFeatures = tableFeatures({
  columnFilteringFeature,
  globalFilteringFeature,
  rowSortingFeature,
  filteredRowModel: createFilteredRowModel(),
  sortedRowModel: createSortedRowModel(),
