export function formatM2Error(error: unknown) {
  if (error instanceof M2ClientError) {
    if (error.status === 401) return "Sign in with an administrator account to continue.";
    if (error.status === 403) return "Your system role does not allow this action.";
    if (error.status === 409) return "The change conflicts with the current identity state.";
    if (error.status === 429) return "Too many attempts. Wait a moment and try again.";
    return error.message;
  }
  return error instanceof Error && error.message
    ? error.message
    : "The request could not be completed.";
}
export function getSetupRedirect(pathname: string, status: number, available: boolean) {
  const normalizedPath = pathname.length > 1 ? pathname.replace(/\/+$/, "") : pathname;

  if (normalizedPath === "/setup") {
    return status === 404 ? "/sign-in" : undefined;
  }

  return available ? "/setup" : undefined;
}
