      {
        params: "M2.IdentifierParams",
        requirePermission: "teams:write",
        response: "M2.TeamStatus",
      },
    )
    .post(
      "/teams/:id/enable",
      async ({ actor, params, request }) =>
        setTeamDisabled(environment, actor, params.id, false, request),
      {
        params: "M2.IdentifierParams",
        requirePermission: "teams:write",
        response: "M2.TeamStatus",
