      {
        body: "M2.TeamMemberBody",
        params: "M2.IdentifierParams",
        requirePermission: "teams:write",
        response: "M2.TeamMember",
      },
    )
    .delete(
      "/teams/:id/members/:userId",
      async ({ actor, params, request }) =>
        removeTeamMember(environment, actor, params.id, params.userId, request),
      {
        params: "M2.TeamMemberParams",
        requirePermission: "teams:write",
        response: "M2.TeamMember",
      },
    )
    .get(
      "/service-accounts",
      async () => ({ serviceAccounts: await listServiceAccounts(environment) }),
      { requirePermission: "service-accounts:read", response: "M2.ServiceAccounts" },
    )
    .post(
