      {
        body: "M2.ServiceAccountCreateBody",
        requirePermission: "service-accounts:write",
        response: "M2.ServiceAccount",
      },
    )
    .patch(
      "/service-accounts/:id",
      async ({ actor, body, params, request }) =>
        updateServiceAccount(environment, actor, params.id, body, request),
      {
        body: "M2.ServiceAccountUpdateBody",
        params: "M2.IdentifierParams",
        requirePermission: "service-accounts:write",
