} from "./admin-layout";

export function TeamsAdminPage() {
  const queryClient = useQueryClient();
  const teamsQuery = useQuery({ queryFn: getTeams, queryKey: ["m2", "teams"], retry: false });
  const usersQuery = useQuery({ queryFn: getUsers, queryKey: ["m2", "users"], retry: false });
  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [busyId, setBusyId] = useState<string>();
  const [error, setError] = useState<string>();
  const [status, setStatus] = useState<string>();

  async function refresh(message?: string) {
    await queryClient.invalidateQueries({ queryKey: ["m2", "teams"] });
    await queryClient.invalidateQueries({ queryKey: ["m2", "users"] });
    if (message) setStatus(message);
  }

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(undefined);
    setStatus(undefined);
    setBusyId("create");
    try {
      await createTeam({ description: description || undefined, name });
      setName("");
      setDescription("");
      await refresh("Team created.");
    } catch (submitError) {
      setError(formatApiError(submitError));
    } finally {
      setBusyId(undefined);
    }
  }

  async function runTeamAction(id: string, action: () => Promise<unknown>, message: string) {
    setBusyId(id);
    setError(undefined);
    setStatus(undefined);
    try {
      await action();
      await refresh(message);
    } catch (actionError) {
      setError(formatApiError(actionError));
    } finally {
      setBusyId(undefined);
    }
  }

  const teams = teamsQuery.data?.teams ?? [];
  const users = usersQuery.data?.users ?? [];

  return (
    <AdminLayout
      activePath="/teams"
      description="Teams contain human Users only. Membership is explicit, flat, and easy to audit; a disabled team no longer represents an active group."
      eyebrow="Principals / Teams"
      title="Put people in useful groups."
    >
      <div className="space-y-8">
        <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
          <h2 className="text-xl font-semibold text-kumo-strong">New team</h2>
          <form
            className="mt-5 grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end"
            onSubmit={submit}
          >
            <Input
              id="team-name"
              label="Team name"
              onChange={(event) => setName(event.target.value)}
              required
              value={name}
            />
            <Input
              id="team-description"
              label="Description (optional)"
              onChange={(event) => setDescription(event.target.value)}
              value={description}
            />
            <Button
              aria-busy={busyId === "create"}
              disabled={busyId !== undefined}
              type="submit"
              variant="primary"
            >
              Create team
            </Button>
          </form>
        </LayerCard>
        {teamsQuery.isLoading || usersQuery.isLoading ? (
          <AdminStatus>Loading teams...</AdminStatus>
        ) : null}
        {teamsQuery.isError ? <AdminError>{formatApiError(teamsQuery.error)}</AdminError> : null}
        {usersQuery.isError ? <AdminError>{formatApiError(usersQuery.error)}</AdminError> : null}
        {error ? <AdminError>{error}</AdminError> : null}
        {status ? <AdminStatus>{status}</AdminStatus> : null}
        <Grid gap="sm" variant="2up">
          {teams.map((team) => (
            <TeamCard
              busy={busyId === team.id}
              key={team.id}
              onAddMember={(userId) =>
                runTeamAction(team.id, () => addTeamMember(team.id, { userId }), "Member added.")
              }
              onDelete={() => runTeamAction(team.id, () => deleteTeam(team.id), "Team deleted.")}
              onRemoveMember={(userId) =>
                runTeamAction(team.id, () => removeTeamMember(team.id, userId), "Member removed.")
              }
              onStatus={() => {
                const nextStatus = team.status === "active" ? "disabled" : "active";
                void runTeamAction(
                  team.id,
                  () => setTeamStatus(team.id, nextStatus),
                  nextStatus === "active" ? "Team enabled." : "Team disabled.",
                );
              }}
              onUpdate={(body) =>
                runTeamAction(team.id, () => updateTeam(team.id, body), "Team updated.")
              }
              team={team}
              users={users.filter((user) => user.principalId && user.status === "active")}
            />
          ))}
        </Grid>
      </div>
    </AdminLayout>
  );
}

function TeamCard({
  busy,
  onAddMember,
  onDelete,
  onRemoveMember,
  onStatus,
  onUpdate,
  team,
  users,
