                  onConfirm={() => onRevoke(user, role.key)}
                  title={`Revoke ${role.name} from ${user.name}?`}
                  trigger={
                    <Button
                      aria-label={"Revoke " + role.name + " from " + user.name}
                      disabled={busyId === user.id}
                      type="button"
                      variant="secondary-destructive"
                    >
                      Revoke
                    </Button>
                  }
                />
              </li>
            ))}
          </ul>
        ) : (
          <p className="mt-3 text-sm text-kumo-subtle">No active holders.</p>
        )}
      </div>
    </LayerCard>
  );
}

import { Button, Input, LinkButton } from "@cloudflare/kumo";
import { useState } from "react";

import { createInvitation, formatApiError, type InvitationCreated } from "../lib/api-client";
import { FormError, FormStatus, M1Layout } from "./m1-layout";

export function InviteAdminPage() {
  const [email, setEmail] = useState("");
  const [name, setName] = useState("");
  const [isPending, setIsPending] = useState(false);
  const [error, setError] = useState<string>();
  const [created, setCreated] = useState<InvitationCreated>();

  async function submit(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    setError(undefined);
    setIsPending(true);
    try {
      const invitation = await createInvitation({ email, name: name || undefined });
      setCreated(invitation);
    } catch (submitError) {
      setError(formatApiError(submitError));
    } finally {
      setIsPending(false);
    }
