import { Button, Grid, LayerCard, Select } from "@cloudflare/kumo";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import { useState } from "react";

import {
  formatApiError,
  getSystemRoles,
  getUsers,
  grantUserRole,
  revokeUserRole,
  type SystemRole,
  type User,
} from "../lib/api-client";
import { AdminConfirmDialog, AdminError, AdminLayout, AdminStatus } from "./admin-layout";

export function SystemRolesAdminPage() {
  const queryClient = useQueryClient();
  const rolesQuery = useQuery({
    queryFn: getSystemRoles,
    queryKey: ["m2", "system-roles"],
    retry: false,
  });
  const usersQuery = useQuery({ queryFn: getUsers, queryKey: ["m2", "users"], retry: false });
  const [userId, setUserId] = useState("");
  const [roleKey, setRoleKey] = useState("");
  const [busyId, setBusyId] = useState<string>();
  const [error, setError] = useState<string>();
  const [status, setStatus] = useState<string>();

  async function refresh(message?: string) {
    await queryClient.invalidateQueries({ queryKey: ["m2", "system-roles"] });
    await queryClient.invalidateQueries({ queryKey: ["m2", "users"] });
    if (message) setStatus(message);
  }

  async function grant(event: React.FormEvent<HTMLFormElement>) {
    event.preventDefault();
    if (!userId || !roleKey) return;
    setBusyId(userId);
    setError(undefined);
    setStatus(undefined);
    try {
      await grantUserRole(userId, roleKey);
      await refresh("System role granted.");
    } catch (grantError) {
      setError(formatApiError(grantError));
    } finally {
      setBusyId(undefined);
    }
  }

  async function revoke(user: User, role: string) {
    setBusyId(user.id);
    setError(undefined);
    setStatus(undefined);
    try {
      await revokeUserRole(user.id, role);
      await refresh("System role revoked.");
    } catch (revokeError) {
      setError(formatApiError(revokeError));
    } finally {
      setBusyId(undefined);
    }
  }

  const roles = rolesQuery.data?.roles ?? [];
  const users = (usersQuery.data?.users ?? []).filter(
    (user) => user.principalId && user.status !== "unmanaged",
  );
  const selectedRole = roles.find((role) => role.key === roleKey);

  return (
    <AdminLayout
      activePath="/system-roles"
      description="System Roles operate Shui itself. The root role is recovery-critical; the API refuses to remove or disable the last active root User."
      eyebrow="Authorization"
      title="Make responsibility explicit."
    >
      <div className="space-y-8">
        <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
          <h2 className="text-xl font-semibold text-kumo-strong">Grant a system role</h2>
          <form
            className="mt-5 grid gap-4 md:grid-cols-[1fr_1fr_auto] md:items-end"
            onSubmit={grant}
          >
            <Select
              items={users.map((user) => ({
                label: `${user.name} · ${user.email}`,
                value: user.id,
              }))}
              label="User"
              onValueChange={(value) => setUserId(value ?? "")}
              placeholder="Choose a user"
              required
              value={userId || null}
            />
            <Select
              items={roles.map((role) => ({ label: role.name, value: role.key }))}
              label="System role"
              onValueChange={(value) => setRoleKey(value ?? "")}
              placeholder="Choose a role"
              required
              value={roleKey || null}
            />
            <Button
              aria-busy={busyId === userId}
              disabled={!userId || !roleKey || busyId !== undefined}
              type="submit"
              variant="primary"
            >
              Grant role
            </Button>
          </form>
          {selectedRole ? (
            <p className="mt-4 text-sm leading-6 text-kumo-subtle">{selectedRole.description}</p>
          ) : null}
        </LayerCard>
        {rolesQuery.isLoading || usersQuery.isLoading ? (
          <AdminStatus>Loading role assignments...</AdminStatus>
        ) : null}
        {rolesQuery.isError ? <AdminError>{formatApiError(rolesQuery.error)}</AdminError> : null}
        {usersQuery.isError ? <AdminError>{formatApiError(usersQuery.error)}</AdminError> : null}
        {error ? <AdminError>{error}</AdminError> : null}
        {status ? <AdminStatus>{status}</AdminStatus> : null}
        <Grid gap="sm" variant="3up">
          {roles.map((role) => (
            <RoleCard key={role.key} role={role} users={users} busyId={busyId} onRevoke={revoke} />
          ))}
        </Grid>
      </div>
    </AdminLayout>
  );
}

function RoleCard({
  busyId,
  onRevoke,
  role,
  users,
}: Readonly<{
  busyId: string | undefined;
  onRevoke: (user: User, role: string) => void;
  role: SystemRole;
  users: User[];
}>) {
  const holders = users.filter((user) => user.roles.includes(role.key));
  return (
    <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
      <div className="flex items-start justify-between gap-3">
        <div>
          <h2 className="text-lg font-semibold text-kumo-strong">{role.name}</h2>
          <p className="mt-1 font-mono text-xs text-(--tangerine)">{role.key}</p>
        </div>
        <span className="text-sm text-kumo-subtle">{role.activeGrantCount} active</span>
      </div>
      <p className="mt-4 text-sm leading-6 text-kumo-subtle">{role.description}</p>
      <div className="mt-5 border-t border-kumo-hairline pt-4">
        <h3 className="text-sm font-medium text-kumo-strong">Current holders</h3>
        {holders.length > 0 ? (
          <ul className="mt-3 space-y-2">
            {holders.map((user) => (
              <li className="flex items-center justify-between gap-3 text-sm" key={user.id}>
                <span className="min-w-0 truncate text-kumo-subtle">{user.name}</span>
                <AdminConfirmDialog
                  confirmLabel="Revoke role"
                  description="The user will immediately lose this system role."
                  onConfirm={() => onRevoke(user, role.key)}
                  title={`Revoke ${role.name} from ${user.name}?`}
                  trigger={
                    <Button
                      aria-label={"Revoke " + role.name + " from " + user.name}
                      disabled={busyId === user.id}
                      type="button"
                      variant="secondary-destructive"
                    >
                      Revoke
                    </Button>
                  }
                />
              </li>

                  "Service account updated.",
                )
              }
              teams={teams}
              users={users}
            />
          ))}
        </Grid>
      </div>
    </AdminLayout>
  );
}

function ServiceAccountCard({
  account,
  busy,
  onStatus,
  onTransfer,
  onUpdate,
  teams,
  users,
}: Readonly<{
  account: ServiceAccount;
  busy: boolean;
  onStatus: () => void;
  onTransfer: (body: { ownerId: string; ownerType: "user" | "team" }) => void;
  onUpdate: (body: { description?: string | null; name?: string }) => void;
  teams: Array<{ id: string; name: string }>;
  users: Array<{ id: string; name: string; principalId: string | null }>;
}>) {
  const [name, setName] = useState(account.name);
  const [description, setDescription] = useState(account.description ?? "");
  const [ownerType, setOwnerType] = useState<"user" | "team">(account.owner.type);
  const [ownerId, setOwnerId] = useState(account.owner.id);

  return (
    <LayerCard className="bg-kumo-elevated p-5 ring ring-kumo-line sm:p-6">
      <div className="flex items-start justify-between gap-4">
        <div className="min-w-0">
          <h2 className="truncate text-xl font-semibold text-kumo-strong">{account.name}</h2>
          <p className="mt-1 text-sm text-kumo-subtle">{account.description || "No description"}</p>
        </div>
        <StatusPill status={account.status} />
      </div>
      <form
        className="mt-5 grid gap-3 border-t border-kumo-hairline pt-5"
        onSubmit={(event) => {
          event.preventDefault();
          onUpdate({ description: description || null, name });
        }}
      >
        <Input
          id={"service-name-" + account.id}
          label="Name"
          onChange={(event) => setName(event.target.value)}
          value={name}
        />
        <Input
          id={"service-description-" + account.id}
          label="Description"
          onChange={(event) => setDescription(event.target.value)}
          value={description}
        />
        <div className="flex flex-wrap gap-3">
          <Button disabled={busy} type="submit" variant="ghost">
            Save details
          </Button>
          <Button disabled={busy} onClick={onStatus} type="button" variant="ghost">
            {account.status === "active" ? "Disable" : "Enable"}
          </Button>
        </div>
      </form>
      <div className="mt-5 border-t border-kumo-hairline pt-5">
        <p className="text-sm text-kumo-subtle">
          Current owner: <span className="font-medium text-kumo-strong">{account.owner.label}</span>{" "}
          ({account.owner.type})
        </p>
        <form
          className="mt-4 grid gap-3 sm:grid-cols-2"
          onSubmit={(event) => {
            event.preventDefault();
            if (ownerId) onTransfer({ ownerId, ownerType });
          }}
        >
          <Select
            items={[
              { label: "User", value: "user" },
              { label: "Team", value: "team" },
            ]}
            label="Transfer to"
            onValueChange={(value) => {
              const nextType = value === "team" ? "team" : "user";
              setOwnerType(nextType);
              setOwnerId("");
            }}
            value={ownerType}
          />
          <Select
            items={
              ownerType === "user"
                ? users.map((user) => ({
                    label: user.name,
                    value: user.principalId ?? "",
                  }))
                : teams.map((team) => ({ label: team.name, value: team.id }))
            }
            label="Owner"
            onValueChange={(value) => setOwnerId(value ?? "")}
            placeholder="Choose an owner"
            required
