import { edenFetch } from "@elysiajs/eden";
import { createFileRoute } from "@tanstack/react-router";
import { createIsomorphicFn } from "@tanstack/react-start";

import { type ApiApp, createApiApp } from "../server/api";

const handle = ({ request }: { request: Request }) => createApiApp(env).fetch(request);

export const Route = createFileRoute("/api/$")({
  server: {
    handlers: {
      DELETE: handle,
      GET: handle,
      HEAD: handle,
      OPTIONS: handle,
      PATCH: handle,
      POST: handle,
      PUT: handle,
    },
  },
});

export const getApiFetch = createIsomorphicFn()
  .server(() =>
    edenFetch<ApiApp>(env.BETTER_AUTH_URL, {
      fetcher: async (input, init) =>
        createApiApp(env).fetch(new Request(input, stripBodyForSafeMethods(init))),
    }),
  )
  .client(() =>
    edenFetch<ApiApp>(window.location.origin, {
      fetcher: async (input, init) => fetch(input, stripBodyForSafeMethods(init)),
    }),
  );

function stripBodyForSafeMethods(init: RequestInit = {}) {
  const method = init.method?.toUpperCase() ?? "GET";
  if (method !== "GET" && method !== "HEAD") return init;

  const headers = new Headers(init.headers);
  headers.delete("content-type");
  const { body: _body, ...safeInit } = init;
  return { ...safeInit, headers };
}
import { Elysia } from "elysia";

import { type AuthEnvironment, type AuthInstance } from "../auth";
import { ApiError } from "./errors";
import { assertMutationOrigin } from "./http";
import { createBootstrapRoutes } from "./bootstrap/routes";
import { createInvitationRoutes } from "./invitations/routes";
import { createServiceAccountRoutes } from "./service-accounts/routes";
import { createSystemRoleRoutes } from "./system-roles/routes";
import { createTeamRoutes } from "./teams/routes";
import { createUserRoutes } from "./users/routes";

export function createApiRoutes(environment: AuthEnvironment, auth: AuthInstance) {
  return new Elysia({ name: "shui-api-routes", normalize: false })
    .error({ ApiError })
    .onBeforeHandle(({ request, set }) => {
      if (["POST", "PUT", "PATCH", "DELETE"].includes(request.method)) {
        assertMutationOrigin(environment, request);
      }
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
    })
    .onError(({ code, error, set }) => {
      set.headers["cache-control"] = "no-store";
      set.headers.pragma = "no-cache";
      const statusCode =
        error instanceof ApiError ? error.statusCode : code === "VALIDATION" ? 400 : 500;
      set.status = statusCode;
      return {
        error: statusCode >= 500 ? "Request failed." : "The request could not be completed.",
      };
    })
    .use(createBootstrapRoutes(environment, auth))
    .use(createInvitationRoutes(environment, auth))
    .use(createUserRoutes(environment, auth))
    .use(createSystemRoleRoutes(environment, auth))
    .use(createTeamRoutes(environment, auth))
    .use(createServiceAccountRoutes(environment, auth));
}
import { Elysia, t } from "elysia";

import { type AuthEnvironment, createAuth } from "./auth";
import { createApiRoutes } from "./modules";

export function createApiApp(environment: AuthEnvironment) {
  const auth = createAuth(environment);

  return new Elysia({ aot: false, prefix: "/api" })
    .onRequest(async ({ request }) => requireApiResource(request))
    .use(createApiRoutes(environment, auth))
    .get("/health", () => ({ service: "shui-api", status: "ok" as const }), {
      response: t.Object({
        service: t.String(),
        status: t.Literal("ok"),
      }),
    })
    .head("/health", () => new Response(null, { status: 204 }))
    .mount(auth.handler);
}

export type ApiApp = ReturnType<typeof createApiApp>;

async function requireApiResource(request: Request) {
  const url = new URL(request.url);
  const isAuthorize = url.pathname.endsWith("/oauth2/authorize");
  const isToken = url.pathname.endsWith("/oauth2/token");
  if (!isAuthorize && !isToken) return;

  if (isAuthorize) {
    const params = request.method === "GET" ? url.searchParams : await readOAuthBody(request);
    const scopes = params.get("scope")?.split(/\s+/) ?? [];
    if (scopes.includes("api:read") && !params.getAll("resource").some(Boolean)) {
      return invalidResourceResponse();
    }
    return;
  }

  const body = await readOAuthBody(request);
  if (body.get("grant_type") === "client_credentials" && !body.getAll("resource").some(Boolean)) {
    return invalidResourceResponse();
  }
}

async function readOAuthBody(request: Request) {
  const contentType = request.headers.get("content-type") ?? "";
  if (contentType.includes("application/x-www-form-urlencoded")) {
    return new URLSearchParams(await request.clone().text());
  }

  if (contentType.includes("application/json")) {
    const body = (await request
      .clone()
      .json()
      .catch(() => null)) as Record<string, unknown> | null;
    const params = new URLSearchParams();
    if (typeof body?.grant_type === "string") params.set("grant_type", body.grant_type);
    if (typeof body?.scope === "string") params.set("scope", body.scope);
    if (typeof body?.resource === "string") params.append("resource", body.resource);
    if (Array.isArray(body?.resource)) {
      for (const resource of body.resource) {
        if (typeof resource === "string") params.append("resource", resource);
      }
    }
    return params;
  }

  return new URLSearchParams();
}

function invalidResourceResponse() {
  return new Response(
    JSON.stringify({
      error: "invalid_target",
      error_description: "The api:read scope requires a resource indicator.",
    }),
    { headers: { "content-type": "application/json" }, status: 400 },
  );
}

