import { Elysia } from "elysia";

import { type AuthEnvironment, type AuthInstance } from "../../auth";
import { requirePermission, requireRole, type SystemPermission } from "./service";

export function createAuthorizationPlugin(environment: AuthEnvironment, auth: AuthInstance) {
  return new Elysia({ name: "shui-authorization" }).macro({
    requireRole: (roles: readonly string[]) => ({
      resolve: async ({ request }) => ({
        actor: await requireRole(auth, environment, request, roles),
      }),
    }),
    requirePermission: (permission: SystemPermission) => ({
      resolve: async ({ request }) => ({
        actor: await requirePermission(auth, environment, request, permission),
      }),
    }),
  });
}
import { and, eq, isNull } from "drizzle-orm";

import { createDb } from "../../../db";
import {
  humanPrincipals,
  principals,
  systemRoleGrants,
  systemRoles,
} from "../../../db/domain-schema";
import { type AuthEnvironment, type AuthInstance } from "../../auth";
import { ApiError } from "../errors";

export type Actor = {
  principalId: string;
  userId: string;
  roleKeys: Set<string>;
};

export const SYSTEM_ROLE_PERMISSIONS = {
  root: ["*"] as const,
  "user-admin": [
    "users:read",
    "users:write",
    "teams:read",
    "teams:write",
    "system-roles:read",
  ] as const,
  "application-admin": ["service-accounts:read", "service-accounts:write"] as const,
};

export type SystemPermission =
  (typeof SYSTEM_ROLE_PERMISSIONS)[keyof typeof SYSTEM_ROLE_PERMISSIONS][number];

export async function getActor(auth: AuthInstance, environment: AuthEnvironment, request: Request) {
  const session = await auth.api.getSession({
    headers: request.headers,
    query: { disableCookieCache: true, disableRefresh: true },
  });
  if (!session?.user) throw new ApiError(401);

  const db = createDb(environment.DB);
  const principal = await db
    .select({ principalId: principals.id, userId: humanPrincipals.userId })
    .from(humanPrincipals)
    .innerJoin(principals, eq(principals.id, humanPrincipals.principalId))
    .where(
      and(
        eq(humanPrincipals.userId, session.user.id),
        eq(humanPrincipals.status, "active"),
        eq(humanPrincipals.disabled, false),
        eq(principals.type, "human"),
        eq(principals.status, "active"),
      ),
    )
    .get();
  if (!principal || principal.userId !== session.user.id) throw new ApiError(401);

  const roleRows = await db
    .select({ key: systemRoles.key })
    .from(systemRoleGrants)
    .innerJoin(systemRoles, eq(systemRoles.id, systemRoleGrants.roleId))
    .where(
      and(
        eq(systemRoleGrants.principalId, principal.principalId),
        isNull(systemRoleGrants.revokedAt),
      ),
    )
    .all();

  return {
    principalId: principal.principalId,
    roleKeys: new Set(roleRows.map((row) => row.key)),
    userId: session.user.id,
  } satisfies Actor;
}

export async function requireRole(
  auth: AuthInstance,
  environment: AuthEnvironment,
  request: Request,
  roles: readonly string[],
) {
  const actor = await getActor(auth, environment, request);
  if (!roles.some((role) => actor.roleKeys.has(role))) throw new ApiError(403);
  return actor;
}

export async function requirePermission(
  auth: AuthInstance,
  environment: AuthEnvironment,
  request: Request,
  permission: SystemPermission,
) {
  const actor = await getActor(auth, environment, request);
  const allowed = [...actor.roleKeys].some((roleKey) => {
    const permissions: readonly string[] =
      SYSTEM_ROLE_PERMISSIONS[roleKey as keyof typeof SYSTEM_ROLE_PERMISSIONS] ?? [];
    return permissions.includes("*") || permissions.includes(permission);
  });
  if (!allowed) throw new ApiError(403);
  return actor;
}

import { Elysia } from "elysia";

import { type AuthEnvironment, type AuthInstance } from "../auth";
import { createAuthorizationPlugin } from "./authorization/plugin";
import { ApiModels } from "./models";

export function createDomainApiRoutes(
  environment: AuthEnvironment,
  auth: AuthInstance,
  name: string,
) {
  return new Elysia({ name: `shui-${name}-routes`, normalize: false })
    .use(createAuthorizationPlugin(environment, auth))
    .model(ApiModels);
}
export const apiStatusCodes = [400, 401, 403, 404, 409, 429, 500] as const;

export type ApiStatusCode = (typeof apiStatusCodes)[number];

export class ApiError extends Error {
  readonly status: ApiStatusCode;

  constructor(readonly statusCode: ApiStatusCode) {
    super("The request could not be completed.");
    this.name = "ApiError";
    this.status = statusCode;
  }
}
import { type AuthEnvironment } from "../auth";
import { ApiError } from "./errors";

export function assertMutationOrigin(environment: AuthEnvironment, request: Request) {
  if (request.headers.get("sec-fetch-site") === "cross-site") throw new ApiError(403);

  const expectedOrigin = new URL(environment.BETTER_AUTH_URL).origin;
  const origin = request.headers.get("origin");
  if (origin && origin !== expectedOrigin) throw new ApiError(403);

  const referer = request.headers.get("referer");
  if (!origin && referer) {
    try {
      if (new URL(referer).origin !== expectedOrigin) throw new ApiError(403);
    } catch (error) {
      if (error instanceof ApiError) throw error;
      throw new ApiError(403);
    }
  }
}

